/// The tenant accent. One preset is chosen from bootstrap branding; custom accents come as a copy.
class AlliedBrand extends ThemeExtension<AlliedBrand> {
  const AlliedBrand({
    required this.accentDefault,
    required this.accentHover,
    required this.accentSubtle,
    required this.accentOn,
  });

  final Color accentDefault;
  final Color accentHover;
  final Color accentSubtle;
  final Color accentOn;

  /// The product accent, used when a tenant has no brand of its own.
  static const AlliedBrand defaultBrand = AlliedBrand(
    accentDefault: Color(0xFF2349C2),
    accentHover: Color(0xFF1A3794),
    accentSubtle: Color(0xFFE6ECF8),
    accentOn: Color(0xFFFFFFFF),
  );

  /// Tenant accent preset.
  static const AlliedBrand teal = AlliedBrand(
    accentDefault: Color(0xFF0F766E),
    accentHover: Color(0xFF0B5C56),
    accentSubtle: Color(0xFFE0F2F0),
    accentOn: Color(0xFFFFFFFF),
  );

  /// Tenant accent preset.
  static const AlliedBrand amber = AlliedBrand(
    accentDefault: Color(0xFFB4540A),
    accentHover: Color(0xFF8F4208),
    accentSubtle: Color(0xFFFCEBDD),
    accentOn: Color(0xFFFFFFFF),
  );

  /// Tenant accent preset.
  static const AlliedBrand plum = AlliedBrand(
    accentDefault: Color(0xFF7A2E8E),
    accentHover: Color(0xFF5F2370),
    accentSubtle: Color(0xFFF3E6F6),
    accentOn: Color(0xFFFFFFFF),
  );

  @override
  AlliedBrand copyWith({
    Color? accentDefault,
    Color? accentHover,
    Color? accentSubtle,
    Color? accentOn,
  }) {
    return AlliedBrand(
      accentDefault: accentDefault ?? this.accentDefault,
      accentHover: accentHover ?? this.accentHover,
      accentSubtle: accentSubtle ?? this.accentSubtle,
      accentOn: accentOn ?? this.accentOn,
    );
  }

  @override
  AlliedBrand lerp(AlliedBrand? other, double t) {
    if (other == null) return this;
    return AlliedBrand(
      accentDefault: Color.lerp(accentDefault, other.accentDefault, t)!,
      accentHover: Color.lerp(accentHover, other.accentHover, t)!,
      accentSubtle: Color.lerp(accentSubtle, other.accentSubtle, t)!,
      accentOn: Color.lerp(accentOn, other.accentOn, t)!,
    );
  }
}

/// The spacing scale, in logical pixels.
abstract final class AlliedSpace {
  static const double s0 = 0;
  static const double s1 = 4;
  static const double s2 = 8;
  static const double s3 = 12;
  static const double s4 = 16;
  static const double s5 = 20;
  static const double s6 = 24;
  static const double s8 = 32;
  static const double s10 = 40;
  static const double s12 = 48;
  static const double s16 = 64;
  static const double s0_5 = 2;
}

/// Corner radii, in logical pixels.
abstract final class AlliedRadius {
  static const double sm = 6;
  static const double md = 8;
  static const double lg = 12;
  static const double xl = 16;
  static const double xxl = 20;
  static const double full = 9999;
}

/// Motion durations.
abstract final class AlliedDuration {
  static const Duration fast = Duration(milliseconds: 150);
  static const Duration base = Duration(milliseconds: 200);
  static const Duration slow = Duration(milliseconds: 250);
}

/// Motion curves.
abstract final class AlliedCurves {
  static const Cubic standard = Cubic(0.2, 0, 0, 1);
  static const Cubic exit = Cubic(0.3, 0, 1, 1);
}

/// A font family with its fallbacks, for [TextStyle.fontFamily] and [TextStyle.fontFamilyFallback].
class FontFamily {
  const FontFamily(this.name, this.fallback);

  final String name;
  final List<String> fallback;
}

/// Font families. Indic scripts get a Noto family first.
abstract final class AlliedFontFamily {
  static const FontFamily sans = FontFamily('IBM Plex Sans', ['Noto Sans']);
  static const FontFamily mono = FontFamily('IBM Plex Mono', []);
  static const FontFamily tamil = FontFamily('Noto Sans Tamil', ['IBM Plex Sans']);
  static const FontFamily devanagari = FontFamily('Noto Sans Devanagari', ['IBM Plex Sans']);
  static const FontFamily telugu = FontFamily('Noto Sans Telugu', ['IBM Plex Sans']);
  static const FontFamily kannada = FontFamily('Noto Sans Kannada', ['IBM Plex Sans']);
  static const FontFamily malayalam = FontFamily('Noto Sans Malayalam', ['IBM Plex Sans']);
}

/// Font weights.
abstract final class AlliedFontWeight {
  static const FontWeight regular = FontWeight.w400;
  static const FontWeight medium = FontWeight.w500;
  static const FontWeight semibold = FontWeight.w600;
  static const FontWeight bold = FontWeight.w700;
}

