/// Control and table sizes for the two densities. Phones use comfortable; tablets may use compact.
class AlliedDensity {
  const AlliedDensity({
    required this.controlHeightSm,
    required this.controlHeightMd,
    required this.controlHeightLg,
    required this.controlPaddingX,
    required this.tableRowHeight,
    required this.tableCellPaddingX,
  });

  final double controlHeightSm;
  final double controlHeightMd;
  final double controlHeightLg;
  final double controlPaddingX;
  final double tableRowHeight;
  final double tableCellPaddingX;

  static const AlliedDensity comfortable = AlliedDensity(
    controlHeightSm: 32,
    controlHeightMd: 40,
    controlHeightLg: 48,
    controlPaddingX: 16,
    tableRowHeight: 52,
    tableCellPaddingX: 16,
  );

  static const AlliedDensity compact = AlliedDensity(
    controlHeightSm: 28,
    controlHeightMd: 32,
    controlHeightLg: 40,
    controlPaddingX: 12,
    tableRowHeight: 40,
    tableCellPaddingX: 12,
  );
}
